#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long m;
    cin >> m;
    vector<vector<long long>> edges(m, vector<long long>(2));
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < 2; j++) {
            cin >> edges[i][j];
        }
    }

    int count = (int)m + 1;
    vector<vector<int>> adj(count + 1);
    for (const vector<long long>& e : edges) {
        adj[e[0]].push_back((int)e[1]);
        adj[e[1]].push_back((int)e[0]);
    }
    auto farthest = [&](int start, long long& far) {
        vector<long long> dist(count + 1, -1);
        dist[start] = 0;
        vector<int> queue = {start};
        for (size_t i = 0; i < queue.size(); i++) {
            int v = queue[i];
            for (int w : adj[v]) {
                if (dist[w] < 0) {
                    dist[w] = dist[v] + 1;
                    queue.push_back(w);
                }
            }
        }
        far = dist[queue.back()];
        return queue.back();
    };
    long long ignored = 0, diameter = 0;
    int a = farthest(1, ignored);
    farthest(a, diameter);
    cout << diameter << "\n";

    return 0;
}

